import {emitterContext} from './emitters.js';

export function createMailViews({esc,icon,toast,modal,isAdmin,beforeAction,compose,navigate}){
 const ports={ssl:465,starttls:587,none:25};
 async function request(path,data){const response=await fetch(path,data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:undefined);const value=await response.json();if(!response.ok)throw Error(value.error||'No se ha podido completar la operación de correo.');return value;}
 const when=value=>new Date(value).toLocaleString('es-ES',{dateStyle:'medium',timeStyle:'short'});
 function button(invoice){return invoice.isExample?'':`<button class="btn" data-mail-send="${esc(invoice.id)}">${icon('mail')} Enviar por correo</button>`;}
 function historySlot(invoice){return invoice.isExample?'':`<section class="mail-history" id="mail-history" data-invoice="${esc(invoice.id)}" aria-live="polite" hidden></section>`;}
 async function loadHistory(invoice){const slot=document.querySelector('#mail-history');if(!slot||invoice.isExample)return;
  try{const {emails}=await request('/api/invoices/'+encodeURIComponent(invoice.id)+'/emails');if(!slot.isConnected||slot.dataset.invoice!==invoice.id)return;
   slot.hidden=!emails.length;slot.innerHTML=emails.length?`<h3>Enviada por correo</h3><div class="movement-list">${emails.map(e=>`<div class="movement"><div><strong>${esc(e.recipients.join(', '))}</strong><small>${esc(when(e.sentAt))}${e.sentBy?' · '+esc(e.sentBy):''}${e.number!==invoice.number?' · como '+esc(e.number):''}</small></div></div>`).join('')}</div>`:'';
  }catch{slot.hidden=true;}}
 async function openDialog(invoiceId){
  await beforeAction();const config=await request('/api/mail/config'),draft=compose(invoiceId);if(!draft)return;
  modal.className='';
  if(!config.ready){modal.innerHTML=`<button class="iconbtn close" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button><h2>Enviar por correo</h2><p>${isAdmin()?'Configura primero la cuenta de correo desde la que este emisor envía sus facturas.':'Un administrador debe configurar primero la cuenta de correo de este emisor.'}</p><div class="actions">${isAdmin()?`<button class="btn primary" data-mail-settings>${icon('settings')} Configurar correo</button>`:''}<button class="btn ghost" data-action="close-modal">Cerrar</button></div>`;if(!modal.open)modal.showModal();return;}
  modal.innerHTML=`<button class="iconbtn close" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button><h2>Enviar factura ${esc(draft.number)}</h2><p>Se adjuntará el PDF conservado. Se envía desde ${esc(config.fromName?config.fromName+' · ':'')}${esc(config.fromAddress)}.</p><form id="mail-send-form" data-invoice="${esc(invoiceId)}"><div class="fields"><div class="field full"><label for="mail-to">Para</label><input id="mail-to" name="to" type="email" multiple required value="${esc(draft.to)}" autocomplete="off" spellcheck="false" aria-describedby="mail-to-help"><small id="mail-to-help">${draft.to?'Correo del cliente. ':'El cliente no tiene correo guardado. '}Separa varios correos con comas.</small></div><div class="field full"><label for="mail-subject">Asunto</label><input id="mail-subject" name="subject" required maxlength="200" value="${esc(draft.subject)}"></div><div class="field full"><label for="mail-message">Mensaje</label><textarea id="mail-message" name="message" rows="7" maxlength="5000">${esc(draft.message)}</textarea></div></div><div class="form-error" role="alert"></div><div class="actions"><button type="button" class="btn ghost" data-action="close-modal">Cancelar</button><button type="submit" class="btn primary">${icon('mail')} Enviar</button></div></form>`;
  if(!modal.open)modal.showModal();const input=modal.querySelector(draft.to?'#mail-subject':'#mail-to');input.focus();}
 function settingsSlot(){return isAdmin()?`<section class="panel formpanel mail-settings" id="mail-settings"><div class="sectionhead"><h2>Correo de envío</h2>${icon('mail')}</div><p class="summary-note">Cargando configuración…</p></section>`:'';}
 async function loadSettings(){const slot=document.querySelector('#mail-settings');if(!slot)return;
  let config;try{config=await request('/api/mail/config');}catch(error){slot.querySelector('.summary-note').textContent=error.message;return;}
  if(!slot.isConnected)return;const security=config.security||'ssl',readonly=!emitterContext.active.active;
  slot.innerHTML=`<div class="sectionhead"><h2>Correo de envío</h2>${icon('mail')}</div><p class="summary-note">Cuenta desde la que este emisor envía sus facturas. La contraseña se guarda cifrada en el servidor. Gmail: smtp.gmail.com, SSL/TLS 465 y una contraseña de aplicación. Microsoft 365: smtp.office365.com, STARTTLS 587.</p><form id="mail-config-form"><div class="fields"><div class="field"><label for="mail-host">Servidor SMTP</label><input id="mail-host" name="host" value="${esc(config.host||'')}" required maxlength="253" placeholder="smtp.empresa.es" autocomplete="off" spellcheck="false"></div><div class="field"><label for="mail-security">Seguridad</label><select id="mail-security" name="security">${[['ssl','SSL/TLS'],['starttls','STARTTLS'],['none','Sin cifrado (solo este equipo)']].map(([value,label])=>`<option value="${value}" ${security===value?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label for="mail-port">Puerto</label><input id="mail-port" name="port" type="number" min="1" max="65535" required value="${esc(config.port||ports[security])}"></div><div class="field"><label for="mail-username">Usuario</label><input id="mail-username" name="username" value="${esc(config.username||'')}" maxlength="254" autocomplete="off" spellcheck="false"><small>Normalmente, la dirección de correo completa.</small></div><div class="field"><label for="mail-password">Contraseña</label><input id="mail-password" name="password" type="password" maxlength="1000" autocomplete="new-password" placeholder="${config.hasPassword?'Guardada · déjala vacía para conservarla':''}"></div><div class="field"><label for="mail-from">Correo del remitente</label><input id="mail-from" name="fromAddress" type="email" required maxlength="254" value="${esc(config.fromAddress||'')}"></div><div class="field"><label for="mail-from-name">Nombre del remitente</label><input id="mail-from-name" name="fromName" maxlength="120" value="${esc(config.fromName||'')}" placeholder="Si lo dejas vacío, la razón social"></div></div><div class="form-error" role="alert"></div><div class="actions"><button class="btn primary" type="submit" ${readonly?'disabled':''}>${icon('check')} Guardar correo</button>${config.ready?`<button class="btn" type="button" data-mail-check ${readonly?'disabled':''}>Probar conexión</button><button class="btn ghost" type="button" data-mail-remove ${readonly?'disabled':''}>Quitar configuración</button>`:''}</div></form>`;
  if(readonly)slot.querySelectorAll('input,select').forEach(element=>element.disabled=true);}
 document.addEventListener('change',event=>{if(event.target.id!=='mail-security')return;const port=document.querySelector('#mail-port');if(port&&(!port.value||Object.values(ports).includes(+port.value)))port.value=ports[event.target.value];});
 document.addEventListener('click',async event=>{const target=event.target.closest('[data-mail-send],[data-mail-check],[data-mail-remove],[data-mail-settings]');if(!target)return;
  if(target.hasAttribute('data-mail-settings')){modal.close();await navigate('settings');document.querySelector('#mail-settings')?.scrollIntoView({block:'start'});return;}
  try{target.disabled=true;
   if(target.dataset.mailSend){await openDialog(target.dataset.mailSend);return;}
   if(target.hasAttribute('data-mail-check')){await request('/api/mail/check',{});toast('Conexión con el servidor de correo confirmada.');return;}
   if(!confirm('¿Quitar la configuración de correo de este emisor? Los envíos registrados se conservan.'))return;
   await request('/api/mail/config',{remove:true});await loadSettings();toast('Configuración de correo retirada.');
  }catch(error){toast(error.message);}finally{if(target.isConnected)target.disabled=false;}});
 document.addEventListener('submit',async event=>{const form=event.target;if(!['mail-send-form','mail-config-form'].includes(form.id))return;event.preventDefault();
  const button=form.querySelector('[type=submit]'),error=form.querySelector('.form-error');button.disabled=true;error.textContent='';
  try{const fields=Object.fromEntries(new FormData(form));
   if(form.id==='mail-config-form'){await request('/api/mail/config',{...fields,port:Number(fields.port)});await loadSettings();toast('Correo de envío guardado.');return;}
   button.textContent='Enviando…';const {email}=await request('/api/invoices/'+encodeURIComponent(form.dataset.invoice)+'/email',fields);
   modal.close();toast('Factura enviada a '+email.recipients.join(', '));const slot=document.querySelector('#mail-history');if(slot?.dataset.invoice===form.dataset.invoice)await loadHistory({id:form.dataset.invoice,number:email.number});
  }catch(exc){error.textContent=exc.message;if(form.isConnected){button.disabled=false;if(form.id==='mail-send-form')button.innerHTML=`${icon('mail')} Enviar`;}}});
 return {button,historySlot,loadHistory,settingsSlot,loadSettings};
}
